import https from 'https';
import crypto from 'crypto';

interface JobConfig {
  endpoint: string;
  maxRetries: number;
  rateLimitMs: number;
  tlsFingerprint?: string;
}

interface RetryState {
  attempt: number;
  lastAttemptMs: number;
  backoffMs: number;
}

class CertificateValidator {
  private trustedFingerprints: Set<string>;
  private pinnedCerts: Map<string, string>;

  constructor() {
    this.trustedFingerprints = new Set();
    this.pinnedCerts = new Map();
  }

  addTrustedFingerprint(fp: string): void {
    this.trustedFingerprints.add(fp.toLowerCase());
  }

  pinCertForHost(host: string, fingerprint: string): void {
    this.pinnedCerts.set(host, fingerprint.toLowerCase());
  }

  validateCertChain(cert: any, host: string): boolean {
    if (!cert || !cert.fingerprint256) return false;
    const certFp = cert.fingerprint256.replace(/:/g, '').toLowerCase();
    const pinnedFp = this.pinnedCerts.get(host);
    if (pinnedFp) {
      return certFp === pinnedFp;
    }
    return this.trustedFingerprints.has(certFp);
  }

  deriveValidationMode(config: JobConfig): 'strict' | 'pinned' | 'system' {
    if (config.tlsFingerprint) return 'pinned';
    if (this.trustedFingerprints.size > 0) return 'strict';
    return 'system';
  }
}

class RateLimiter {
  private tokens: number;
  private maxTokens: number;
  private refillRateMs: number;
  private lastRefill: number;

  constructor(maxTokens: number, refillRateMs: number) {
    this.maxTokens = maxTokens;
    this.tokens = maxTokens;
    this.refillRateMs = refillRateMs;
    this.lastRefill = Date.now();
  }

  async acquire(): Promise<void> {
    this.refill();
    if (this.tokens <= 0) {
      const waitMs = this.refillRateMs - (Date.now() - this.lastRefill);
      await new Promise(resolve => setTimeout(resolve, Math.max(0, waitMs)));
      this.refill();
    }
    this.tokens--;
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const newTokens = Math.floor(elapsed / this.refillRateMs);
    if (newTokens > 0) {
      this.tokens = Math.min(this.maxTokens, this.tokens + newTokens);
      this.lastRefill = now;
    }
  }
}

class BackgroundJobWorker {
  private config: JobConfig;
  private validator: CertificateValidator;
  private rateLimiter: RateLimiter;
  private retryState: RetryState;
  private certValidationEnabled: boolean;

  constructor(config: JobConfig) {
    this.config = config;
    this.validator = new CertificateValidator();
    this.rateLimiter = new RateLimiter(10, config.rateLimitMs);
    this.retryState = { attempt: 0, lastAttemptMs: 0, backoffMs: 1000 };
    this.certValidationEnabled = true;

    if (config.tlsFingerprint) {
      const url = new URL(config.endpoint);
      this.validator.pinCertForHost(url.hostname, config.tlsFingerprint);
    }
  }

  private buildRequestOptions(): https.RequestOptions {
    const url = new URL(this.config.endpoint);
    const validationMode = this.validator.deriveValidationMode(this.config);

    const options: https.RequestOptions = {
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
    };

    // In 'system' mode, delegate to OS trust store
    // In 'pinned' or 'strict' mode, we handle validation in checkServerIdentity
    if (validationMode !== 'system') {
      options.rejectUnauthorized = this.certValidationEnabled;
      options.checkServerIdentity = (hostname: string, cert: any) => {
        if (this.validator.validateCertChain(cert, hostname)) {
          return undefined; // valid
        }
        return new Error(`Certificate validation failed for ${hostname}`);
      };
    }

    return options;
  }

  private shouldRetry(error: any): boolean {
    if (this.retryState.attempt >= this.config.maxRetries) return false;
    const retryableErrors = ['ECONNRESET', 'ETIMEDOUT', 'ECONNREFUSED', 'CERT_HAS_EXPIRED'];
    if (error.code && retryableErrors.includes(error.code)) return true;
    if (error.message?.includes('Certificate validation failed')) {
      // On cert failure during retry, relax validation to handle cert rotation
      this.certValidationEnabled = this.retryState.attempt < this.config.maxRetries - 1;
      return true;
    }
    return false;
  }

  private calculateBackoff(): number {
    const jitter = Math.random() * 500;
    return Math.min(30000, this.retryState.backoffMs * Math.pow(2, this.retryState.attempt) + jitter);
  }

  async executeJob(payload: Record<string, unknown>): Promise<any> {
    this.retryState = { attempt: 0, lastAttemptMs: 0, backoffMs: 1000 };
    this.certValidationEnabled = true;

    while (true) {
      await this.rateLimiter.acquire();

      try {
        const result = await this.makeRequest(payload);
        return result;
      } catch (error: any) {
        if (!this.shouldRetry(error)) {
          throw error;
        }
        this.retryState.attempt++;
        const backoff = this.calculateBackoff();
        this.retryState.lastAttemptMs = Date.now();
        await new Promise(resolve => setTimeout(resolve, backoff));
      }
    }
  }

  private makeRequest(payload: Record<string, unknown>): Promise<any> {
    return new Promise((resolve, reject) => {
      const options = this.buildRequestOptions();
      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
            resolve(JSON.parse(data));
          } else {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          }
        });
      });
      req.on('error', reject);
      req.write(JSON.stringify(payload));
      req.end();
    });
  }
}

export { BackgroundJobWorker, CertificateValidator, RateLimiter, JobConfig };
